"use client";

/** Host adapter for the Apache-2.0 scan UI by Gustavo Fior (@gustavo-fior), Abdul Haidar, and Foglamp Labs. */
import { createContext, useContext, type ReactNode } from "react";
import { getGoogleFavicon } from "../../widgets/leaf/favicon";

const FaviconContext = createContext(getGoogleFavicon);

/** Supply your image endpoint or asset resolver without changing map markup. */
export function ScanFaviconProvider({ resolve, children }: {
  resolve: (domain: string) => string;
  children: ReactNode;
}) {
  return <FaviconContext.Provider value={resolve}>{children}</FaviconContext.Provider>;
}

export function useScanFavicon() {
  return useContext(FaviconContext);
}

/* Original design and implementation by Gustavo Fior (@gustavo-fior), with co-founder Abdul Haidar at Foglamp Labs.
 * Extracted from .reference/foglamp/apps/web/src/lib/favicon.ts; derived here under Apache-2.0.
 */
export const getGoogleFavicon = (domain: string) => {
	if (domain.includes("https://") || domain.includes("http://")) {
		return `https://t3.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=${domain}&size=256`;
	} else {
		return `https://t3.gstatic.com/faviconV2?client=SOCIAL&type=FAVICON&fallback_opts=TYPE,SIZE,URL&url=https://${domain}&size=256`;
	}
};
